SELECT concert.Concert_ID, singer.Name, concert.Stadium_ID, concert.Year FROM concert JOIN singer_in_concert ON concert.Concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Capacity BETWEEN 5000 AND 10000;
