SELECT s.first_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Departments d ON ssec.degree_program_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Student_Enrolment se ON se.student_id = s.student_id JOIN Transcripts t ON se.student_id = t.transcript_id JOIN Transcript_Contents tc ON tc.transcript_id = t.transcript_id JOIN Addresses a ON s.current_address_id = a.address_id JOIN Student_Enrolment_Courses sc2 ON s.current_address_id = sc2.student_course_id JOIN Courses c2 ON sc2.course_id = c2.course_id JOIN Sections ssec2 ON ssec2.section_id = ssec2.section_id JOIN Semesters ssem2 ON ssem2.semester_id = ssem2.semester_id JOIN Departments d2 ON d2.department_id = d2.department_id JOIN Degree_Programs dp2 ON dp2.department_id = d2.department_id JOIN Student_Enrolment se2 ON se2.student_id = s.student_id JOIN Transcripts t2 ON se2.student_id = t2.transcript_id JOIN Transcript_Contents tc2 ON tc2.transcript_id = t2.transcript_id WHERE s.first_name = 'Undergraduate' ORDER BY s.student_id DESC;
SELECT s.semester_name, s.student_id FROM Semesters s JOIN Student_Enrolment_Courses c ON s.semester_id = c.semester_id JOIN Courses ON c.course_id = Courses.course_id JOIN Students ON c.student_id = Students.student_id JOIN Addresses ON Students.current_address_id = Addresses.address_id JOIN Student_Enrolment ON Students.student_id = Student_Enrolment.student_id JOIN Degree_Programs ON Student_Enrolment.degree_program_id = Degree_Programs.degree_program_id GROUP BY s.semester_name, s.student_id ORDER BY s.semester_name, s.student_id LIMIT 1;
SELECT course_description FROM Courses WHERE course_name LIKE '%computer%'
SELECT DISTINCT t.transcript_id, t.transcript_date, t.transcript_Contents.* FROM Transcript_Contents t JOIN Student_Enrolment_Courses sc ON t.student_course_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s ON c.course_id = s.section_id JOIN Departments d ON s.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Students s2 ON s2.student_id = s.student_id JOIN Addresses a ON s.current_address_id = a.address_id JOIN Transcripts t2 ON t.transcript_id = t2.transcript_id JOIN Semester s2 ON s2.semester_id = s.semester_id JOIN Transcripts t3 ON t3.transcript_id = t2.transcript_id JOIN Semester s3 ON s3.semester_id = s2.semester_id;
SELECT s.first_name, s.middle_name, s.last_name, s.id FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON ssec.section_id = sc.section_id JOIN Semester ssem ON ssem.semester_id = sc.semester_id JOIN Degree_Programs d ON d.degree_program_id = sc.degree_program_id JOIN Departments dpt ON d.department_id = dpt.department_id;
SELECT S.first_name, S.middle_name, S.last_name, S.student_id, D.department_id, D.department_name FROM Students S JOIN Degree_Programs D ON S.student_id = D.degree_program_id WHERE D.department_id = (SELECT department_id FROM Departments) AND D.degree_program_id IN (SELECT degree_program_id FROM Degree_Programs WHERE degree_summary_name = '2 degree programs') ORDER BY S.first_name, S.middle_name, S.last_name;
SELECT first_name, middle_name, last_name FROM Students ORDER BY last_name;
SELECT S.first_name, S.middle_name, S.last_name FROM Students S INNER JOIN Addresses A ON S.current_address_id = A.address_id INNER JOIN Courses C ON S.permanent_address_id = A.address_id INNER JOIN Departments D ON S.current_address_id = A.address_id INNER JOIN Degree_Programs DP ON S.current_address_id = A.address_id INNER JOIN Sections S2 ON S.current_address_id = A.address_id INNER JOIN Transcripts T ON S.current_address_id = A.address_id
SELECT D.degree_summary_name, COUNT(D.degree_program_id) AS total_students_enrolled FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id GROUP BY D.degree_summary_name ORDER BY total_students_enrolled DESC;
SELECT DISTINCT Degree_Programs.degree_summary_name, COUNT(DISTINCT Students.student_id) AS student_count FROM Degree_Programs JOIN Students ON Degree_Programs.department_id = Students.department_id GROUP BY Degree_Programs.degree_summary_name;
SELECT D.degree_program_id, S.first_name, D.degree_summary_name FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id JOIN Degree_Programs ON D.degree_program_id = D.degree_program_id ORDER BY D.degree_summary_name ASC LIMIT 1
SELECT D.Degree_Programs.degree_program_id, D.degree_summary_name, D.degree_summary_description FROM Degree_Programs D INNER JOIN Students S ON D.department_id = S.department_id INNER JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id INNER JOIN Courses C ON SC.course_id = C.course_id INNER JOIN Sections S1 ON S.section_id = S1.section_id INNER JOIN Departments D1 ON D.department_id = D1.department_id GROUP BY D.degree_program_id, D.degree_summary_name, D.degree_summary_description ORDER BY D.degree_summary_description DESC
