nrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment_Courses.course_id, s.student_Enrolment
