SELECT s.id, s.line_1, s.line_2 FROM Addresses s JOIN Student_Enrolment_Courses sc ON s.address_id = sc.student_enrolment_id JOIN Students s2 ON s2.student_id = s.id GROUP BY s.id ORDER BY s.id DESC LIMIT 1;
