SELECT o.Orchestra, p.Year_of_Founded, p.Weekly_rank, p.Share FROM orchestra o JOIN performance p ON o.Orchestra_ID = p.Orchestra_ID JOIN show s ON p.Performance_ID = s.Performance_ID ORDER BY p.Year_of_Founded DESC;
SELECT orchestra.Orchestra, performance.Type, performance.Date, performance.Weekly_rank, performance.Share FROM orchestra JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID ORDER BY performance.Year_of_Founded DESC;
SELECT AVG(show.Attendance) AS average_guest FROM show;
SELECT AVG(Show.Attendance) AS average_guest FROM show JOIN performance ON show.Performance_ID = performance.Performance_ID JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID;
SELECT MAX(Share), MIN(Share) FROM performance WHERE Type != 'Live final'
SELECT MAX(Performance.Share), MIN(Performance.Share) FROM performance INNER JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.Type != 'Live final'
SELECT COUNT(DISTINCT conductor.Nationality) FROM conductor;
SELECT DISTINCT conductor.Nationality FROM conductor;
SELECT conductor.Name, conductor.Age, conductor.Nationality, conductor.Year_of_Work FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID ORDER BY conductor.Year_of_Work DESC;
SELECT Name, Year_of_Work FROM conductor ORDER BY Year_of_Work DESC;
SELECT conductor.Name, conductor.Age, conductor.Nationality, conductor.Conductor_ID, conductor.Year_of_Work, conductor.Year_of_Founded, conductor.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = '1' AND show.Year_of_Founded = (SELECT MAX(Year_of_Founded) FROM show) ORDER BY conductor.Year_of_Work DESC;
SELECT conductor.Name, conductor.Age, conductor.Nationality FROM conductor JOIN performance ON conductor.Conductor_ID = performance.Orchestra_ID JOIN orchestra ON orchestra.Orchestra_ID = performance.Orchestra JOIN show ON show.Performance_ID = performance.Performance_ID ORDER BY conductor.Age DESC;
SELECT conductor.Name, orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, orchestra.Record_Company, performance.Year_of_Founded, performance.Weekly_rank, performance.Share FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = 'Yes';
SELECT conductor.Name FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID INNER JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID INNER JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = 'Yes' AND show.Attendance IS NOT NULL;
SELECT Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID WHERE show.If_first_show = 'No' AND show.Record_Company = 'No' AND show.Record_Company IS NULL;
SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, orchestra.Record_Company, conductor.Age, conductor.Nationality, orchestra.Year_of_Founded, performance.Weekly_rank, show.Attendance FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID INNER JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID INNER JOIN show ON show.Performance_ID = performance.Performance_ID ORDER BY performance.Weekly_rank DESC;
SELECT conductor.Name, conductor.Age, conductor.Nationality, conductor.Year_of_Work, orchestra.Orchestra, orchestra.Record_Company, orchestra.Founded_year, orchestra.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Major_Record_Format = (SELECT * FROM performance) GROUP BY conductor.Name, conductor.Age, conductor.Nationality, conductor.Year_of_Work, orchestra.Orchestra, orchestra.Record_Company, orchestra.Founded_year, orchestra.Major_Record_Format
SELECT conductor.Name, orchestra.Year_of_Founded FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded > 2008;
SELECT conductor.Name FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded > 2008;
SELECT conductor.Name, COUNT(orchestra.Orchestra) AS ensemble_count FROM conductor JOIN orchestra ON orchestra.Conductor_ID = conductor.Conductor_ID GROUP BY conductor.Name
SELECT COUNT(*) AS total_ensembles, COUNT(DISTINCT enterprise_id) AS unique_ensembles FROM enterprise JOIN conductor ON conductor.Conductor_ID = enterprise.Conductor_ID JOIN orchestra ON orchestra.Orchestra_ID = conductor.Orchestra_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID;
SELECT orchestra.Orchestra, COUNT(orchestra.Orchestra) AS count FROM orchestra GROUP BY orchestra.Orchestra ORDER BY count ASC;
SELECT Major_Record_Format, COUNT(*) AS Frequency FROM orchestra GROUP BY Major_Record_Format ORDER BY Frequency ASC
SELECT orchestra.Orchestra, COUNT(performance.Performance_ID) AS total_shows FROM orchestra JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID GROUP BY orchestra.Orchestra, performance.Performance_ID ORDER BY total_shows DESC
SELECT DISTINCT orchestra.Orchestra, COUNT(orchestra.Orchestra) AS ensemble_count FROM conductor JOIN orchestra ON orchestra.Conductor_ID = conductor.Conductor_ID GROUP BY orchestra.Orchestra ORDER BY ensemble_count DESC LIMIT 1;
SELECT orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Orchestra_ID WHERE orchestra.Record_Company IS NULL
SELECT orchestra.Orchestra FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Age IS NULL;
SELECT orchestra.Orchestra_ID, orchestra.Year_of_Founded FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Age < 2003 OR conductor.Age > 2003;
SELECT DISTINCT orchestra.Orchestra_ID FROM conductor c JOIN orchestra o ON o.Conductor_ID = c.Conductor_ID WHERE c.Age < 2003 OR c.Age > 2003
SELECT COUNT(*) FROM orchestra JOIN performance ON orchestra.Orchestra = performance.Orchestra_ID WHERE performance.Type IN ('CD', 'DVD')
SELECT COUNT(*) FROM orchestra WHERE orchestra.Record_Company = 'CD' OR orchestra.Record_Company = 'DVD' AND orchestra.Conductor_ID IS NOT NULL;
SELECT Year_of_Founded FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Record_Company IS NOT NULL AND orchestra.Year_of_Founded IS NOT NULL
SELECT o.Year_of_Founded, p.Type, p.Date, p.Official_ratings_(millions), p.Weekly_rank, p.Share FROM orchestra o JOIN performance p ON o.Orchestra_ID = p.Orchestra_ID WHERE p.Type = 'Show' AND p.Official_ratings_(millions) > 1000000 AND p.Weekly_rank > 0 ORDER BY o.Year_of_Founded DESC;
SELECT COUNT(*) FROM Highschooler;
SELECT COUNT(*) AS student_count FROM Highschooler;
