SELECT name FROM Highschooler WHERE grade = '10' GROUP BY name;
SELECT Highschooler.ID FROM Highschooler WHERE name = 'Kyle'
SELECT DISTINCT Highschooler.ID FROM Highschooler;
SELECT COUNT(*) FROM Highschooler WHERE grade IN ('9', '10')
SELECT COUNT(*) FROM Highschooler WHERE grade IN ('9', '10')
SELECT DISTINCT grade, COUNT(*) AS num_students FROM Highschooler GROUP BY grade;
SELECT DISTINCT grade, COUNT(*) AS student_count FROM Highschooler GROUP BY grade;
SELECT grade FROM Highschooler ORDER BY COUNT(*) DESC;
SELECT grade FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend JOIN Likes ON Friend.friend_id = Likes.student_id GROUP BY student_id ORDER BY COUNT(*) DESC LIMIT 1)
SELECT DISTINCT grade FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend JOIN Likes ON Friend.friend_id = Likes.student_id WHERE Likes.liked_id = Highschooler.ID AND COUNT(*) >= 4)
SELECT grade FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend JOIN Likes ON Friend.friend_id = Likes.student_id GROUP BY student_id HAVING COUNT(*) >= 4)
SELECT Highschooler.ID, Highschooler.name, Highschooler.grade, Friend.friend_id FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.friend_id;
SELECT COUNT(DISTINCT student_id) FROM Friend;
SELECT Highschooler.name, COUNT(Friend.friend_id) AS friends FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id GROUP BY Highschooler.name;
SELECT name, COUNT(Friend.friend_id) AS num_friends FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name;
SELECT name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name ORDER BY COUNT(Friend.friend_id) DESC LIMIT 1;
SELECT name, COUNT(*) AS friend_count FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name ORDER BY friend_count DESC LIMIT 1
SELECT DISTINCT name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name HAVING COUNT(Friend.friend_id) >= 3
SELECT name FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend WHERE COUNT(Friend.friend_id) > 3)
