SELECT Highschooler.ID FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id WHERE Highschooler.ID NOT IN (SELECT Friend.friend_id FROM Friend JOIN Highschooler ON Friend.friend_id = Highschooler.ID)
SELECT DISTINCT Highschooler.ID FROM Highschooler WHERE Highschooler.ID NOT IN (SELECT Friend.student_id FROM Friend)
SELECT name FROM Highschooler WHERE id NOT IN (SELECT student_id FROM Friend WHERE friend_id = NULL OR id IS NULL)
SELECT name FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend JOIN Likes ON Friend.student_id = Likes.student_id GROUP BY student_id HAVING COUNT(*) = 0)
SELECT DISTINCT Highschooler.ID FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id JOIN Likes ON Highschooler.ID = Likes.student_id;
SELECT DISTINCT Highschooler.ID FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id INNER JOIN Likes ON Highschooler.ID = Likes.student_id WHERE Friend.friend_id IS NOT NULL AND Likes.liked_id IS NOT NULL;
SELECT name FROM Highschooler WHERE name IN (SELECT name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id JOIN Likes ON Highschooler.ID = Likes.student_id WHERE Likes.liked_id IS NOT NULL)
SELECT name FROM Highschooler WHERE ID IN (SELECT Friend.student_id FROM Friend JOIN Highschooler ON Friend.friend_id = Highschooler.ID AND Likes.student_id = Highschooler.ID)
SELECT DISTINCT Highschooler.ID, COUNT(*) AS likes FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY Highschooler.ID;
SELECT DISTINCT Highschooler.ID, COUNT(*) AS likes_per_student FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY Highschooler.ID
SELECT DISTINCT Highschooler.name, COUNT(Likes.liked_id) AS likes_count FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY Highschooler.name;
SELECT DISTINCT student_id, COUNT(*) AS likes FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY student_id;
SELECT name FROM Highschooler JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY name ORDER BY likes DESC LIMIT 1
SELECT name FROM Highschooler JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY name ORDER BY likes DESC LIMIT 1;
SELECT name FROM Highschooler WHERE name IN (SELECT name FROM Friend JOIN Likes ON Friend.friend_id = Likes.liked_id WHERE Likes.liked_id = Highschooler.ID AND Likes.like_count >= 2)
SELECT name FROM Highschooler WHERE name IN (SELECT name FROM Friend JOIN Likes ON Friend.friend_id = Likes.liked_id GROUP BY name HAVING COUNT(name) > 1)
