SELECT name FROM Highschooler WHERE grade > 5 AND (SELECT COUNT(*) > 2 FROM Highschooler) GROUP BY name
SELECT COUNT(DISTINCT student_id) FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY student_id;
