SELECT AVG(Highschooler.grade) FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT AVG(Highschooler.grade) FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT MIN(grade) FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE friend_id IS NULL)
SELECT DISTINCT grade FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE student_id IS NULL OR student_id IS NULL OR (SELECT Friend.friend_id FROM Friend WHERE Friend.student_id IS NULL))
