SELECT Dogs.name FROM Dogs WHERE Dogs.date_departed IS NULL AND Dogs.date_arrived IS NULL AND Dogs.date_of_birth IS NULL
SELECT Dogs.name, Professionals.first_name, Professionals.last_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id WHERE Dogs.date_of_birth IS NULL OR Dogs.date_of_birth > '2000-01-01' AND Dogs.date_departed IS NULL OR Dogs.date_departed > '2000-01-01' AND Treatments.cost_of_treatment > 1000
SELECT DISTINCT first_name FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id WHERE Dogs.gender = 'dog' AND Dogs.breed_code = 'dog' AND Dogs.size_code = 'dog' AND Dogs.name = '' AND Dogs.date_of_birth = '' AND Dogs.date_arrived = '' AND Dogs.date_departed = '' AND Professionals.role_code = 'guardian' AND Professionals.first_name IS NOT NULL;
SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE d.breed_code = (SELECT breed_code FROM Breeds) AND d.size_code = (SELECT size_code FROM Sizes) AND o.first_name NOT IN (SELECT first_name FROM Dogs WHERE name = 'dog') AND o.first_name NOT IN (SELECT first_name FROM Professionals WHERE role_code = 'guardian')
SELECT o.owner_id, p.role, o.email_address FROM Owners o JOIN Professionals p ON o.owner_id = p.professional_id WHERE p.role != 'Veterinarian' AND p.role IS NULL;
SELECT Dogs.id, Dogs.role, Dogs.email_address FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Professionals.role_code = 'Veterinarian' AND Professionals.email_address NOT IN (SELECT email_address FROM Treatments WHERE treatment_type_code = 'Health Care' AND dog_id = (SELECT dog_id FROM Dogs WHERE abandoned_yn = 'Y'))
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.date_arrived, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id WHERE d.abandoned_yn = 'N' AND d.date_of_birth IS NOT NULL;
SELECT Dogs.owner_id, Dogs.name, Dogs.family_name, COUNT(Dogs.dog_id) AS total_dogs FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id GROUP BY Dogs.owner_id ORDER BY COUNT(Dogs.dog_id) DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.role, Dogs.first_name, Dogs.last_name, Dogs.name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.role = 'Professional' AND Dogs.name IS NOT NULL AND Dogs.age > 0;
SELECT Dogs.id, Dogs.role, Dogs.first_name AS first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Professionals.role_code = 'Veterinarian' AND Dogs.dog_id IN (SELECT Dog_id FROM Charges WHERE charge_type = 'Health Care' AND charge_amount > 0 AND charge_id IN (SELECT charge_id FROM Charges WHERE charge_type = 'Health Care' AND charge_amount > 0))
SELECT breed_name FROM Breeds WHERE breed_code = (SELECT breed_code FROM Dogs WHERE name = (SELECT MAX(age) FROM Dogs))
SELECT breed_name FROM Breeds ORDER BY breed_name DESC LIMIT 1
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.date_arrived, d.date_departed, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t_type ON t.treatment_type_code = t_type.treatment_type_code JOIN Professionals p ON t.professional_id = p.professional_id GROUP BY o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.date_arrived, d.date_departed, t.cost_of_treatment ORDER BY t.cost_of_treatment DESC;
SELECT o.owner_id, d.name, p.first_name, p.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.owner_id = p.professional_id JOIN Treatment_Types t ON d.dog_id = t.treatment_type_code JOIN Charges c ON d.dog_id = c.dog_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code JOIN Treatments t2 ON d.dog_id = t2.dog_id WHERE c.charge_amount > (SELECT MAX(c.charge_amount) FROM Charges c) ORDER BY c.charge_amount DESC;
SELECT MIN(cost_of_treatment) AS cost_of_treatment FROM Treatments;
SELECT Dogs.name, Dogs.weight, Dogs.date_of_birth, Dogs.date_arrived, Dogs.date_departed, Dogs.abandoned_yn, Dogs.dog_id, Dogs.owner_id, Dogs.breed_code, Dogs.size_code, Dogs.gender, Dogs.date_of_birth, Dogs.date_arrived, Dogs.date_departed, Dogs.abandoned_yn FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Charges.charge_amount = (SELECT MIN(charge_amount) FROM Charges) ORDER BY Charges.charge_amount ASC;
SELECT o.owner_id, t.zip_code FROM Owners o JOIN Treatments t ON o.owner_id = t.dog_id JOIN Dogs d ON d.owner_id = o.owner_id GROUP BY o.owner_id ORDER BY t.cost_of_treatment DESC LIMIT 1;
SELECT Dogs.guardian_id, Dogs.zip_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY Dogs.guardian_id, Dogs.zip_code ORDER BY SUM(Dogs.charge_amount) DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.cell_number FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'Y' OR Dogs.cell_number IS NOT NULL;
SELECT Dogs.id, Dogs.cell_number FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'Y' OR Dogs.cell_number IS NOT NULL;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON t.professional_id = p.professional_id WHERE t.cost_of_treatment < 10000000;
SELECT o.first_name, o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.date_arrived, d.date_departed, p.first_name, p.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE d.charge_amount < (SELECT AVG(charge_amount) FROM Charges) AND d.charge_type = 'medical care' AND d.breed_code = (SELECT breed_code FROM Breeds) AND d.size_code = (SELECT size_code FROM Sizes) AND d.date_of_birth IS NOT NULL;
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.date_of_birth, Professionals.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id;
SELECT Dogs.dog_id, Dogs.name, Dogs.weight, Treatments.cost_of_treatment, Treatment_Types.treatment_type_description AS treatment_type_description FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Dogs.dog_id IS NOT NULL;
SELECT Dogs.name, Dogs.weight, Treatment_Types.treatment_type_description, Treatment_Types.treatment_type_code AS treatment_type_code FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
